import uk.org.okapibarcode.graphics.Color;
import uk.org.okapibarcode.output.SvgRenderer;
import java.io.ByteArrayOutputStream;

public class BarcodeSvgTest {
    public static void main(String[] args) throws Exception {
        // Test EAN13 with 12 digits (no check digit)
        testEan13("123456789012", "12 digits (no check digit)");
        // Test EAN13 with 13 digits (with check digit)
        testEan13("1234567890128", "13 digits (with check digit)");
        // Test UPC-A with 11 digits (no check digit)
        testUpcA("12345678901", "11 digits (no check digit)");
        // Test UPC-A with 12 digits (with check digit)
        testUpcA("123456789012", "12 digits (with check digit)");
    }

    static void testEan13(String value, String desc) {
        System.out.println("=== EAN13: " + desc + " ===");
        System.out.println("Input value: " + value);
        try {
            Ean ean = new Ean(Ean.Mode.EAN13);
            ean.setHumanReadableLocation(HumanReadableLocation.BOTTOM);
            ean.setContent(value);
            ByteArrayOutputStream out = new ByteArrayOutputStream();
            SvgRenderer renderer = new SvgRenderer(out, 2.0, Color.WHITE, Color.BLACK, true, 0);
            renderer.render(ean);
            String svg = out.toString();
            System.out.println("getContent: " + ean.getContent());
            System.out.println("getHumanReadableText: " + ean.getHumanReadableText());
            // Print the text elements in the SVG
            int idx = 0;
            while ((idx = svg.indexOf("<text", idx)) != -1) {
                int end = svg.indexOf("</text>", idx);
                if (end != -1) {
                    System.out.println("TEXT: " + svg.substring(idx, end + 7));
                }
                idx += 5;
            }
        } catch (Exception e) {
            System.out.println("ERROR: " + e.getMessage());
            e.printStackTrace();
        }
        System.out.println();
    }

    static void testUpcA(String value, String desc) {
        System.out.println("=== UPCA: " + desc + " ===");
        System.out.println("Input value: " + value);
        try {
