            renderer.render(upc);
            String svg = out.toString();
            System.out.println("getContent: " + upc.getContent());
            System.out.println("getHumanReadableText: " + upc.getHumanReadableText());
            int idx = 0;
            while ((idx = svg.indexOf("<text", idx)) != -1) {
                int end = svg.indexOf("</text>", idx);
                if (end != -1) {
                    System.out.println("TEXT: " + svg.substring(idx, end + 7));
                }
                idx += 5;
            }
        } catch (Exception e) {
            System.out.println("ERROR: " + e.getMessage());
            e.printStackTrace();
        }
        System.out.println();
    }
}
