		if p.pos >= len(p.expr) {
			break
		}
		op := p.expr[p.pos]
		if op == '=' || op == '!' || op == '<' || op == '>' {
			p.pos++
			if op == '!' && p.pos < len(p.expr) && p.expr[p.pos] == '=' {
				p.pos++
				op = '!'
			} else if (op == '<' || op == '>') && p.pos < len(p.expr) && p.expr[p.pos] == '=' {
				p.pos++
				op = op + '='
			}
			right, err := p.parseTerm()
			if err != nil {
				return nil, err
			}
			left = &binaryExpr{op: string(op), left: left, right: right}
		} else {
			break
		}
	}
	return left, nil
}

