package xpath

import (
	"fmt"
	"strings"
)

// Query represents a compiled XPath query.
type Query struct {
	expr interface{}
}

// Compile parses and compiles an XPath expression.
func Compile(expr string) (*Query, error) {
	e, err := Parse(expr)
	if err != nil {
		return nil, err
	}
	return &Query{expr: e}, nil
}

// Eval evaluates the compiled query against the given context.
func (q *Query) Eval(ctx *Context) (interface{}, error) {
	return q.expr.(Expr).Eval(ctx)
}

// Context provides evaluation context for XPath expressions.
type Context struct {
	Root *Node
	Node  *Node
}

// EvalPath evaluates a path expression against the context.
func (ctx *Context) EvalPath(path string) (interface{}, error) {
	if ctx.Node == nil {
		return nil, fmt.Errorf("no context node")
	}
	// Simplified path evaluation
	if path == "." {
		return &NodeSet{Nodes: []*Node{ctx.Node}}, nil
	}
	if path == ".." {
		if ctx.Node.Parent != nil {
			return &NodeSet{Nodes: []*Node{ctx.Node.Parent}}, nil
		}
		return &NodeSet{}, nil
	}
	// Handle child paths
	parts := strings.Split(path, "/")
	current := []*Node{ctx.Node}
	for _, part := range parts {
		if part == "" {
			continue
		}
		var next []*Node
		for _, n := range current {
			for _, c := range n.Children {
				if c.Name == part {
					next = append(next, c)
				}
			}
		}
		current = next
	}
	return &NodeSet{Nodes: current}, nil
}

// Node represents an XML node.
type Node struct {
	Name     string
	Value    string
	Children []*Node
	Parent   *Node
}

// NodeSet represents a set of nodes.
type NodeSet struct {
	Nodes []*Node
}

// Expr is an interface for evaluating expressions.
type Expr interface {
	Eval(ctx *Context) (interface{}, error)
}
