```bash
cd /testbed && cat > /tmp/test_all.rs << 'EOF'
use std::cmp::max;

fn resize_dimensions(
    width: u32,
    height: u32,
    nwidth: u32,
    nheight: u32,
    fill: bool,
) -> (u32, u32) {
    let wratio = f64::from(nwidth) / f64::from(width);
    let hratio = f64::from(nheight) / f64::from(height);

    let ratio = if fill {
        f64::max(wratio, hratio)
    } else {
        f64::min(wratio, hratio)
    };

    let nw = max((f64::from(width) * ratio).round() as u64, 1);
    let nh = max((f64::from(height) * ratio).round() as u64, 1);

    if nw > u64::from(u32::MAX) {
        let ratio = f64::from(u32::MAX) / f64::from(width);
        (u32::MAX, max((f64::from(height) * ratio).round() as u32, 1))
    } else if nh > u64::from(u32::MAX) {
        let ratio = f64::from(u32::MAX) / f64::from(height);
        (max((f64::from(width) * ratio).round() as u32, 1), u32::MAX)
    } else {
        (nw as u32, nh as u32)
    }
}

fn main() {
    // resize_handles_fill
    assert_eq!(resize_dimensions(100, 200, 200, 500, true), (250, 500));
    assert_eq!(resize_dimensions(200, 100, 500, 200, true), (500, 250));
    println!("resize_handles_fill OK");

    // resize_never_rounds_to_zero
    let r = resize_dimensions(1, 150, 128, 128, false);
    assert!(r.0 > 0 && r.1 > 0);
    println!("resize_never_rounds_to_zero OK: {:?}", r);

    // resize_handles_overflow
    assert_eq!(resize_dimensions(100, u32::MAX, 200, u32::MAX, true), (100, u32::MAX));
    assert_eq!(resize_dimensions(u32::MAX, 100, u32::MAX, 200, true), (u32::MAX, 100));
    println!("resize_handles_overflow OK");

    // resize_rounds
    assert_eq!(resize_dimensions(4264, 2476, 3840, 2160, true), (3840, 2230));
    assert_eq!(resize_dimensions(2476, 4264, 2160, 3840, false), (2160, 3720));
    println!("resize_rounds OK");

    // resize_handles_zero
    assert_eq!(resize_dimensions(0, 100, 100, 100, false), (1, 100));
    assert_eq!(resize_dimensions(100, 0, 100, 100, false), (100, 1));
    assert_eq!(resize_dimensions(100, 100, 0, 100, false), (1, 1));
    assert_eq!(resize_dimensions(100, 100, 100, 0, false), (1, 1));
    println!("resize_handles_zero OK");

    // The PR reproduction case
    let (nw, nh) = resize_dimensions(3840, 2230, 100, 100, false);
    println!("PR case: {}x{}", nw, nh);
    assert!(nw < u32::MAX && nh < u32::MAX);
    println!("PR case OK");
}
EOF
